package course.domain.validators;

import course.domain.Movie;

import java.time.Year;

/**
 * Validator for Movie entities
 * A movie is valid if:
 * - the id is null (generated by the database at save) or positive
 * - the title and the director are not blank
 * - the year is between 1888 (the first movie) and the current year
 * - the duration is between 1 and 600 minutes
 */
public class MovieValidator implements Validator<Movie> {

    /**
     * all the errors are reported at once, in a single ValidationException
     *
     * @param f - the movie to be validated
     * @throws ValidationException if the movie is null or not valid;
     *                             the message contains all the errors found
     */
    @Override
    public void validate(Movie f) {
        if (f == null)
            throw new ValidationException("Filmul nu poate fi null!");

        StringBuilder errors = new StringBuilder();

        if (f.getId() != null && f.getId() <= 0)
            errors.append("id invalid; ");
        if (f.getTitle() == null || f.getTitle().isBlank())
            errors.append("titlul lipseste; ");
        if (f.getDirector() == null || f.getDirector().isBlank())
            errors.append("regizorul lipseste; ");
        if (f.getYear() < 1888 || f.getYear() > Year.now().getValue())
            errors.append("an invalid (1888 - " + Year.now().getValue() + "); ");
        if (f.getDurationMinutes() < 1 || f.getDurationMinutes() > 600)
            errors.append("durata invalida (1 - 600 minute); ");

        if (!errors.isEmpty())
            throw new ValidationException(errors.toString().trim());
    }
}
